  <div class="market-stalls">${Array.from({length:perPage},(_,i)=>{const p=i===perPage-1?{id:d.me.id,name:state.name}:shown[i],o=p&&(d.offers||[]).find(o=>o.seller===p.id),own=p?.id===d.me.id,online=own||p&&joinedPresence&&!presenceFailed&&visitors.some(v=>v.id===p.id);return p?`<button class="market-stall ${selected===p.id?'chosen':''}" data-market-peer="${esc(p.id)}"><span class="stall-awning" aria-hidden="true"></span><span class="stall-goods" aria-hidden="true">${o?symbols[o.give_item]+(o.want_qty===0?' 🎁':' '+symbols[o.want_item]):'🧺'}</span><b>${esc(p.name)}의 가판대</b><small>${own?'나 · 맡긴 물건 보기':online?'● 함께 있어요':state.trial?'연습 친구의 가판대':'물건만 맡김'}</small></button>`:'<div class="market-stall vacant"><span class="stall-awning"></span><span class="stall-goods">🧺</span><small>이웃의 가판대 자리</small></div>'}).join('')}</div>
