 function position(){const h=$('#marketHero');if(h){h.style.left=(19+(spot%6)*14)+'%';h.style.top=(67+Math.floor(spot/6)*18)+'%'}syncScene()}
 async function sync(greeting){if(!active()||busy)return false;const token=schoolToken;busy=true;try{if(leaving)await leaving;if(!active()||schoolToken!==token)return false;activeToken=token;const d=await schoolFetch('/api/market-presence',{action:greeting?'greet':'visit',...(greeting?{greeting,target:selected}:{spot})},token,8000);if(active()&&schoolToken===token){const now=Date.now(),present=new Set(d.visitors.map(v=>v.id));for(const old of visitors)if(old.id!==d.me&&!present.has(old.id)&&!awayVisitors.has(old.id))awayVisitors.set(old.id,{...old,away:true,until:now+90000,greeting:''});for(const id of present)awayVisitors.delete(id);for(const [id,row] of awayVisitors)if(row.until<=now)awayVisitors.delete(id);visitors=d.visitors;joinedPresence=true;presenceFailed=false;lastPresenceSummary=`${visitors.length}명${awayVisitors.size?` · 자리 비움 ${awayVisitors.size}명`:''}`;const self=visitors.find(v=>v.id===d.me);if(self)spot=self.spot;draw();return true}return false}catch(e){presenceFailed=true;joinedPresence=false;notice=e.name==='AbortError'?'장터 연결이 늦어 다시 시도하고 있어요.':e.message||'방문 상태를 확인하지 못했어요';draw();if(greeting)toast(notice);return false}finally{busy=false;if(!active()||schoolToken!==token){await leave(token)}else if(queuedSpot!==null){const next=queuedSpot;queuedSpot=null;spot=next;position();queueMicrotask(()=>sync())}}}
 async function leave(token=activeToken){if(!token||activeToken!==token)return leaving;if(activeToken===token)activeToken='';queuedSpot=null;const now=Date.now();for(const old of visitors)if(old.id!==classroomData?.me?.id)awayVisitors.set(old.id,{...old,away:true,until:now+90000,greeting:''});visitors=[];joinedPresence=false;presenceFailed=false;const pending=schoolFetch('/api/market-presence',{action:'leave'},token,3000).catch(()=>{});leaving=pending;try{await pending}finally{if(leaving===pending)leaving=null}}
 async function sendGreeting(g){if(!selected||selected===classroomData.me.id){toast('인사할 친구를 먼저 선택해 주세요.');return}if(Date.now()-lastGreeting<5000){toast('인사는 5초 뒤에 다시 보낼 수 있어요.');return}const friend=classroomData.players?.find(p=>p.id===selected),start=Date.now();while(busy&&Date.now()-start<2500)await new Promise(resolve=>setTimeout(resolve,60));if(busy){toast('입장을 확인하고 있어요. 잠시 뒤 인사해 주세요.');return}if(await sync(g)){lastGreeting=Date.now();toast(`${friend?.name||'친구'}에게 인사를 보냈어요. 친구 화면에 곧 전달됩니다.`)}}
 function trade(id){
  const o=classroomData.offers.find(o=>o.id===id);if(!o)return;
  const own=o.seller===classroomData.me.id,gift=o.want_qty===0,here=visitors.some(v=>v.id===o.seller),showFlat=!document.querySelector('.market-plaza.market-3d');
  const have=gift?0:schoolTradeStock(o.want_item),short=!own&&!gift&&have<o.want_qty;
  modal(`<h2>${own?'제안을 취소할까요?':gift?'친구의 나눔을 받을까요?':'서로의 물건을 확인해요'}</h2>${own?`<p>돌려받을 물건: ${symbols[o.give_item]} ${items[o.give_item]} ${o.give_qty}개</p><p>가판대에 맡긴 물건이 내 보관함으로 돌아옵니다.</p>`:`<div class="market-meeting"><div>${showFlat?avatar(classroomData.me.id,true):''}<b>${esc(state.name)}</b><span>${gift?'내가 줄 물건 없음':`${symbols[o.want_item]} ${items[o.want_item]} ${o.want_qty}개 · <span id="marketMeetingStock">내 보관함 ${have}개</span>`}</span></div><span class="meeting-arrow">${gift?'←':'↔'}</span><div>${showFlat?avatar(o.seller):''}<b>${esc(o.seller_name)}</b><span>${symbols[o.give_item]} ${items[o.give_item]} ${o.give_qty}개</span></div></div><p>${gift?'친구가 맡긴 물건을 받을 수 있어요. 내가 내는 물건은 없어요.':here?'친구가 올린 제안에 내가 동의하면 교환됩니다.':'친구가 미리 맡긴 물건이에요. 지금 자리에 없어도 제안대로 교환할 수 있어요.'}</p>`}<p id="marketDialogFeedback" role="alert" class="school-error">${short?'교환할 물건이 부족해요.':''}</p><div class="dialog-actions"><button data-close>돌아가기</button><button id="confirmSchoolTrade" class="primary" ${short?'disabled':''}>${own?'제안 취소하기':gift?'나눔 받기':'이 물건으로 교환하기'}</button></div>`);$('#dialog').dataset.marketOffer=id;
  $('#confirmSchoolTrade').onclick=async()=>{const button=$('#confirmSchoolTrade'),feedback=$('#marketDialogFeedback');button.disabled=true;button.textContent=gift?'나눔 확인 중…':'교환 확인 중…';feedback.textContent=gift?'나눔을 저장하고 있어요.':'교환을 저장하고 있어요.';tradeInProgress=true;const ok=await schoolAction({action:own?'cancel':'accept',offer:id},true);tradeInProgress=false;if(ok){close();notice=own?'물건을 보관함으로 가져왔어요':gift?'🎁 나눔 물건이 내 보관함에 들어왔어요!':'🎁 물건이 서로의 보관함으로 건너갔어요!';draw();const root=$('#marketSquare');root?.classList.add('trade-complete');setTimeout(()=>root?.classList.remove('trade-complete'),1500);toast(notice)}else{feedback.textContent=window.schoolLastActionError||'제안을 마치지 못했어요. 다시 시도해 주세요.';button.disabled=false;button.textContent=own?'제안 취소하기':gift?'나눔 받기':'이 물건으로 교환하기'}};
 }
 const previous=renderPanel;renderPanel=function(){if(window.classroomActive&&document.body.dataset.screen==='market'){draw();return}previous()};
 function changed(){if(active()){draw();if(!wasMarket){const root=$('#marketSquare');root?.classList.remove('market-arriving');void root?.offsetWidth;root?.classList.add('market-arriving');const heading=root?.querySelector('h2');heading?.setAttribute('tabindex','-1');heading?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'})}wasMarket=true;sync()}else{wasMarket=false;leave()}}
 window.addEventListener('resize',()=>{lastKey='';draw()});window.addEventListener('village-screen-change',changed);document.addEventListener('visibilitychange',changed);window.addEventListener('focus',()=>{if(active())sync()});window.addEventListener('pageshow',()=>{if(active())sync()});
 window.addEventListener('pagehide',()=>{if(activeToken)fetch('/api/market-presence',{method:'POST',headers:{'content-type':'application/json',authorization:'Bearer '+activeToken},body:JSON.stringify({action:'leave'}),keepalive:true}).catch(()=>{})});
 async function tick(){if(active())await sync();else if(activeToken)await leave();timer=setTimeout(tick,presenceFailed?1800:4500+Math.random()*1000)}
